static void releaseMouse(void){ClipCursor(NULL);while(ShowCursor(TRUE)<0){}}
static void captureMouse(void){if(!window||!focused)return;RECT r;GetClientRect(window,&r);POINT a={r.left,r.top},b={r.right,r.bottom};ClientToScreen(window,&a);ClientToScreen(window,&b);r.left=a.x;r.top=a.y;r.right=b.x;r.bottom=b.y;ClipCursor(&r);SetCursorPos((a.x+b.x)/2,(a.y+b.y)/2);while(ShowCursor(FALSE)>=0){}}
static void menu(const char *message){if(mode==3&&clientToken){Input empty={0};sendRequest(5,empty);}mode=0;stopNet();releaseMouse();if(message)snprintf(statusText,sizeof(statusText),"%s",message);}
static void startGame(int m){initWorld(&world);rebuildArena();shopOpen=pendingBuy=0;memset(inputs,0,sizeof(inputs));memset(seenShots,0,sizeof(seenShots));myId=0;aimYaw=aimPitch=0;clientSeq=lastSnapTick=0;netNext=0;joinEdit=0;if(m==3){if(!openNet(0)){menu("Could not open a network socket.");return;}memset(&serverAddr,0,sizeof(serverAddr));serverAddr.sin_family=AF_INET;serverAddr.sin_port=htons(PORT);serverAddr.sin_addr.s_addr=inet_addr(address);if(serverAddr.sin_addr.s_addr==INADDR_NONE){menu("Enter a valid IPv4 address.");return;}myId=-1;lastServer=now();nextHello=0;}else{if(m==2&&!openNet(1)){menu("Port 27016 is busy. Close the other host first.");return;}addPlayer(&world,0);aimYaw=world.p[0].yaw;if(m==1)for(int j=1;j<8;j++)addPlayer(&world,j);}mode=m;captureMouse();}
static void clientNetwork(double t){if(myId<0&&t>=nextHello){Input zero={0};sendRequest(1,zero);nextHello=t+.5;}for(int k=0;k<64;k++){Snapshot s;struct sockaddr_in from;int size=sizeof(from);int n=recvfrom(sock,(char*)&s,sizeof(s),0,(struct sockaddr*)&from,&size);if(n<0)break;if(n!=sizeof(s)||!samePeer(&from,&serverAddr)||s.magic!=MAGIC||s.version!=VERSION)continue;if(s.type==4){menu("Server is full (16 players).");return;}if(s.type!=2||s.id<0||s.id>=16)continue;if(clientToken&&s.token!=clientToken)continue;if(myId>=0&&(int32_t)(s.w.tick-lastSnapTick)<0)continue;int first=myId<0;myId=s.id;clientToken=s.token;lastServer=t;lastSnapTick=s.w.tick;int wasDead=world.p[myId].hp<=0;int changedMap=selectedMap!=(int)s.w.mapId;world=s.w;selectedMap=(int)world.mapId;if(changedMap)rebuildArena();if(first||(wasDead&&world.p[myId].hp>0)){aimYaw=world.p[myId].yaw;aimPitch=0;}}
if(t-lastServer>10)menu("Connection timed out. Check IP, UDP 27016 and firewall.");}
/* Grid BFS lets practice opponents navigate the complete arena. */
static Input botInput(int id){Input r={0};Player *p=&world.p[id];r.yaw=p->yaw;int target=-1;float best=1e9f;for(int i=0;i<16;i++){Player *q=&world.p[i];if(!q->active||q->hp<=0||p->team==q->team)continue;float dx=q->x-p->x,dz=q->z-p->z,d=dx*dx+dz*dz;if(d<best){best=d;target=i;}}if(target<0)return r;Player *q=&world.p[target];if(best<2500&&visible(p,q)){float error=botDifficulty==0?.30f:botDifficulty==1?.14f:.055f;uint32_t noise=(world.tick*1103515245u+(uint32_t)id*12345u)>>16;r.yaw=atan2f(q->x-p->x,q->z-p->z)+(((int)(noise%2001)-1000)/1000.0f)*error;r.pitch=-.035f;r.buttons=(world.tick%(botDifficulty==0?30:botDifficulty==1?18:11)==(uint32_t)id%11)?1:0;r.forward=best>100?1:0;}else{int start=(int)(p->z/CELL)*32+(int)(p->x/CELL),goal=(int)(q->z/CELL)*32+(int)(q->x/CELL);int prev[1024],queue[1024],head=0,tail=0;for(int i=0;i<1024;i++)prev[i]=-1;prev[start]=start;queue[tail++]=start;while(head<tail&&prev[goal]<0){int a=queue[head++],x=a%32,z=a/32;int ox[4]={1,-1,0,0},oz[4]={0,0,1,-1};for(int k=0;k<4;k++){int nx=x+ox[k],nz=z+oz[k],b=nz*32+nx;if(nx<0||nx>=32||nz<0||nz>=32||tile(nx,nz)!='.'||prev[b]>=0)continue;prev[b]=a;queue[tail++]=b;}}if(prev[goal]>=0&&goal!=start){int b=goal;while(prev[b]!=start&&prev[b]!=b)b=prev[b];float tx=(b%32+.5f)*CELL,tz=(b/32+.5f)*CELL;r.yaw=atan2f(tx-p->x,tz-p->z);r.forward=1;}}
if(!p->ammo)r.buttons|=2;return r;}
static void soundInit(void){static const float gain[4]={1.0f,.62f,.34f,.15f};unsigned char *b=gunSound[0];memcpy(b,"RIFF",4);uint32_t n=sizeof(gunSound[0])-8;memcpy(b+4,&n,4);memcpy(b+8,"WAVEfmt ",8);n=16;memcpy(b+16,&n,4);uint16_t v=1;memcpy(b+20,&v,2);memcpy(b+22,&v,2);n=16000;memcpy(b+24,&n,4);memcpy(b+28,&n,4);memcpy(b+32,&v,2);v=8;memcpy(b+34,&v,2);memcpy(b+36,"data",4);n=1600;memcpy(b+40,&n,4);for(int i=0;i<1600;i++){float decay=1-(float)i/1600;b[44+i]=(unsigned char)(128+((int)(random32()%200)-100)*decay*decay);}for(int k=1;k<4;k++){memcpy(gunSound[k],gunSound[0],sizeof(gunSound[0]));for(int i=0;i<1600;i++)gunSound[k][44+i]=(unsigned char)(128+((int)gunSound[0][44+i]-128)*gain[k]);}}
static void playGunSound(float distance){if(distance>72)return;int band=distance<14?0:distance<32?1:distance<52?2:3;PlaySoundA((LPCSTR)gunSound[band],NULL,SND_MEMORY|SND_ASYNC|SND_NODEFAULT);}
static float hashNoise(int x,int y){uint32_t n=(uint32_t)x*0x8da6b343u^(uint32_t)y*0xd8163841u;n^=n>>13;n*=0x85ebca6bu;n^=n>>16;return (float)(n&65535u)/65535.0f;}
static float smoothNoise(float x,float y,int scale){float fx=x*scale,fy=y*scale;int ix=(int)floorf(fx),iy=(int)floorf(fy);float u=fx-ix,v=fy-iy;u=u*u*(3-2*u);v=v*v*(3-2*v);float a=hashNoise(ix,iy),b=hashNoise(ix+1,iy),c=hashNoise(ix,iy+1),d=hashNoise(ix+1,iy+1);return (a+(b-a)*u)+((c+(d-c)*u)-(a+(b-a)*u))*v;}
static void createTextures(void){int size=graphicsQuality==0?64:graphicsQuality==1?128:256;glGenTextures(4,tex);for(int k=0;k<4;k++){unsigned char pixels[256*256*3];int base[4][3]={{181,151,119},{161,139,106},{122,83,53},{76,88,96}};int unit=size/4;for(int y=0;y<size;y++)for(int x=0;x<size;x++){float u=(float)x/size,v=(float)y/size;float broad=smoothNoise(u,v,4),mid=smoothNoise(u,v,13),fine=smoothNoise(u,v,37);float detail=(broad-.5f)*24+(mid-.5f)*18+(fine-.5f)*11+(hashNoise(x,y)-.5f)*9;float shade=1.0f;int seam=0;if(k==0){int row=y/unit,withinY=y%unit;int mortarThickness=1+(int)(hashNoise(row,71)*2);int shifted=x+(row&1)*(unit/2);int withinX=shifted%unit;seam=withinY<mortarThickness||withinX<1+(int)(hashNoise(row,shifted/unit)*2);if(seam)shade=.66f;detail+=(broad-.5f)*10;}else if(k==1){detail+=(broad-.5f)*28+(mid-.5f)*10;shade=1.0f;}else if(k==2){float grain=(smoothNoise(u,v,5)-.5f)*25+(smoothNoise(u,v,29)-.5f)*12;detail=grain+(hashNoise(x,y)-.5f)*8;shade=1.0f;}else{float brushed=smoothNoise(u,v,43);detail=(brushed-.5f)*19+(mid-.5f)*9;shade=1.0f;}if(seam)detail*=.30f;for(int c=0;c<3;c++){float tint=(c-1)*(broad-.5f)*7;pixels[(y*size+x)*3+c]=(unsigned char)clampf(base[k][c]*shade+detail+tint,0,255);}}glBindTexture(GL_TEXTURE_2D,tex[k]);glTexImage2D(GL_TEXTURE_2D,0,GL_RGB,size,size,0,GL_RGB,GL_UNSIGNED_BYTE,pixels);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,graphicsQuality==0?GL_NEAREST:GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,graphicsQuality==0?GL_NEAREST:GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_REPEAT);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_REPEAT);}}
static void face(float a,float b,float c,float d,float e,float f,float g,float h,float i,float j,float k,float l,float u,float v){float ux=d-a,uy=e-b,uz=f-c,vx=g-a,vy=h-b,vz=i-c,nx=uy*vz-uz*vy,ny=uz*vx-ux*vz,nz=ux*vy-uy*vx,len=sqrtf(nx*nx+ny*ny+nz*nz);if(len>.0001f)glNormal3f(-nx/len,-ny/len,-nz/len);glTexCoord2f(0,0);glVertex3f(a,b,c);glTexCoord2f(u,0);glVertex3f(d,e,f);glTexCoord2f(u,v);glVertex3f(g,h,i);glTexCoord2f(0,v);glVertex3f(j,k,l);}
static void box(float x,float y,float z,float sx,float sy,float sz,int texture,float r,float g,float b){if(texture>=0){glEnable(GL_TEXTURE_2D);glBindTexture(GL_TEXTURE_2D,tex[texture]);}else glDisable(GL_TEXTURE_2D);float X=x+sx,Y=y+sy,Z=z+sz;glBegin(GL_QUADS);glColor3f(r*.78f,g*.78f,b*.78f);face(x,y,z,X,y,z,X,Y,z,x,Y,z,sx/3,sy/3);face(X,y,Z,x,y,Z,x,Y,Z,X,Y,Z,sx/3,sy/3);glColor3f(r*.9f,g*.9f,b*.9f);face(x,y,Z,x,y,z,x,Y,z,x,Y,Z,sz/3,sy/3);face(X,y,z,X,y,Z,X,Y,Z,X,Y,z,sz/3,sy/3);glColor3f(r,g,b);face(x,Y,z,X,Y,z,X,Y,Z,x,Y,Z,sx/3,sz/3);face(x,y,Z,X,y,Z,X,y,z,x,y,z,sx/3,sz/3);glEnd();}
static void textAt(float x,float y,float size,const char *s,float r,float g,float b){glDisable(GL_TEXTURE_2D);glColor3f(r,g,b);glPushMatrix();glTranslatef(x,y,0);glScalef(size,size,1);glRasterPos2f(0,0);glListBase(font);glCallLists((GLsizei)strlen(s),GL_UNSIGNED_BYTE,s);glPopMatrix();}
