/* Original masonry arches and domed roof silhouettes above walkable space. */
static void arch(float cx,float z,float radius){
 glEnable(GL_TEXTURE_2D);glBindTexture(GL_TEXTURE_2D,tex[0]);
 for(int i=0;i<18;i++){float a=PI*i/18,b=PI*(i+1)/18,inner=radius,outer=radius+.55f;
 float x0=cx+cosf(a)*inner,y0=2.8f+sinf(a)*inner,x1=cx+cosf(b)*inner,y1=2.8f+sinf(b)*inner;
 float X0=cx+cosf(a)*outer,Y0=2.8f+sinf(a)*outer,X1=cx+cosf(b)*outer,Y1=2.8f+sinf(b)*outer;
 glBegin(GL_QUADS);glColor3f(.90f,.86f,.76f);face(x0,y0,z,x1,y1,z,X1,Y1,z,X0,Y0,z,1,1);face(X0,Y0,z+.65f,X1,Y1,z+.65f,x1,y1,z+.65f,x0,y0,z+.65f,1,1);
 glColor3f(.58f,.53f,.43f);face(x0,y0,z+.65f,x1,y1,z+.65f,x1,y1,z,x0,y0,z,1,1);glEnd();}
}
static void dome(float cx,float y,float z,float radius){glDisable(GL_TEXTURE_2D);for(int ring=0;ring<7;ring++){float a=PI*.5f*ring/7,b=PI*.5f*(ring+1)/7;glColor3f(.40f+ring*.025f,.51f+ring*.02f,.49f+ring*.015f);glBegin(GL_QUAD_STRIP);for(int i=0;i<=24;i++){float p=2*PI*i/24;glNormal3f(cosf(p)*cosf(a),sinf(a),sinf(p)*cosf(a));glVertex3f(cx+cosf(p)*cosf(a)*radius,y+sinf(a)*radius,z+sinf(p)*cosf(a)*radius);glNormal3f(cosf(p)*cosf(b),sinf(b),sinf(p)*cosf(b));glVertex3f(cx+cosf(p)*cosf(b)*radius,y+sinf(b)*radius,z+sinf(p)*cosf(b)*radius);}glEnd();}}
static void buildArena(void){glEnable(GL_TEXTURE_2D);glBindTexture(GL_TEXTURE_2D,tex[1]);glColor3f(1,1,1);glBegin(GL_QUADS);face(0,0,0,96,0,0,96,0,96,0,0,96,8,8);glEnd();for(int z=0;z<32;z++)for(int x=0;x<32;x++){int c=tile(x,z);if(c=='#'){float h=5.5f;if(x==0||z==0||x==31||z==31)h=7.5f;if(graphicsQuality==0)box(x*CELL,0,z*CELL,CELL,h,CELL,0,1,1,1);else{box(x*CELL-.06f,0,z*CELL-.06f,CELL+.12f,.42f,CELL+.12f,0,.82f,.77f,.68f);box(x*CELL,.32f,z*CELL,CELL,h-.48f,CELL,0,1,1,1);box(x*CELL-.05f,h-.22f,z*CELL-.05f,CELL+.10f,.22f,CELL+.10f,0,.78f,.74f,.67f);}}else if(c=='c')box(x*CELL,0,z*CELL,CELL,2.6f,CELL,2,1,1,1);}
arch(13.5f,21.2f,4.5f);arch(37.5f,54.2f,4.5f);arch(70.5f,69.2f,4.5f);
box(45,5.5f,24,6,3,6,0,.86f,.86f,.83f);dome(48,8.5f,27,3.4f);
box(21,5.5f,60,3,5,3,0,.87f,.85f,.80f);box(20.7f,9.3f,59.7f,3.6f,.3f,3.6f,0,.66f,.63f,.56f);dome(22.5f,10.5f,61.5f,1.65f);
/* Wooden beams bridge passages; decoration never blocks walkable cells. */
for(int z=9;z<18;z+=3)box(22*CELL,4.5f,z*CELL,9,.28f,.3f,2,.8f,.8f,.8f);
for(int i=0;i<6;i++){float x=2.0f+i*15;box(x,7.5f,.4f,1,1.1f,1,0,.9f,.9f,.9f);}
/* Quality-dependent masonry edging replaces extra clutter props. */
}
