static void toggleFullscreen(void){if(!fullScreen){GetWindowRect(window,&savedWindowRect);savedWindowStyle=(DWORD)GetWindowLongA(window,GWL_STYLE);fullScreen=1;if(!applyResolution()){fullScreen=0;return;}SetWindowLongA(window,GWL_STYLE,WS_POPUP|WS_VISIBLE);SetWindowPos(window,HWND_TOP,0,0,resolutions[resolutionIndex][0],resolutions[resolutionIndex][1],SWP_FRAMECHANGED|SWP_SHOWWINDOW);}else{ChangeDisplaySettingsA(NULL,0);fullScreen=0;SetWindowLongA(window,GWL_STYLE,(LONG)savedWindowStyle);RECT r={0,0,resolutions[resolutionIndex][0],resolutions[resolutionIndex][1]};AdjustWindowRect(&r,savedWindowStyle,FALSE);SetWindowPos(window,NULL,savedWindowRect.left,savedWindowRect.top,r.right-r.left,r.bottom-r.top,SWP_NOZORDER|SWP_FRAMECHANGED|SWP_SHOWWINDOW);}}
