static void drawShadow(float x,float z,float rx,float rz){if(graphicsQuality==0)return;glDisable(GL_LIGHTING);glDisable(GL_TEXTURE_2D);glEnable(GL_BLEND);glBlendFunc(GL_SRC_ALPHA,GL_ONE_MINUS_SRC_ALPHA);glBegin(GL_TRIANGLE_FAN);glColor4f(.02f,.015f,.01f,.28f);glVertex3f(x,.035f,z);for(int i=0;i<=24;i++){float a=2*PI*i/24;glColor4f(.02f,.015f,.01f,0);glVertex3f(x+cosf(a)*rx,.035f,z+sinf(a)*rz);}glEnd();glDisable(GL_BLEND);if(graphicsQuality>=2)glEnable(GL_LIGHTING);}
