static Input localInput(float dt){Input in={0};in.yaw=aimYaw;in.pitch=aimPitch;if(!focused)return in;POINT center={width/2,height/2},p;ClientToScreen(window,&center);GetCursorPos(&p);aimYaw-=(p.x-center.x)*.0023f;aimPitch=clampf(aimPitch-(p.y-center.y)*.0023f,-1.3f,1.3f);SetCursorPos(center.x,center.y);in.yaw=aimYaw;in.pitch=aimPitch;if(!shopOpen){in.forward=(float)(keys[moveKeys[0]]-keys[moveKeys[1]]);in.side=(float)(keys[moveKeys[3]]-keys[moveKeys[2]]);if(GetAsyncKeyState(VK_LBUTTON)&0x8000)in.buttons|=1;if(keys['R'])in.buttons|=2;if(keys[VK_SHIFT])in.buttons|=4;if(in.forward||in.side)bob+=dt*10;}if(pendingBuy){in.buttons|=8u<<(pendingBuy-1);pendingBuy=0;}return in;}
